<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import VChart from 'vue-echarts'
import { use } from 'echarts/core'
import { CanvasRenderer } from 'echarts/renderers'
import { LineChart } from 'echarts/charts'
import { GridComponent, TooltipComponent } from 'echarts/components'
import { Clock, Coin, CircleCheck, Plus, ArrowRight, MoreFilled, Lightning } from '@element-plus/icons-vue'
import { getHealth, getSummary, getWorkflows, runWorkflow } from '../api/tasks'
import type { DashboardSummary, Workflow } from '../types'
import { ElMessage } from 'element-plus'
import { useUiStore } from '../stores/ui'
import { useRuntimeStore } from '../stores/runtime'
import AmbientMotionBackground from '../components/AmbientMotionBackground.vue'
import FloatingContent from '../components/FloatingContent.vue'
use([CanvasRenderer, LineChart, GridComponent, TooltipComponent])
const summary = ref<DashboardSummary | null>(null); const loading = ref(true); const prompt = ref(''); const submitting = ref(false); const health = ref<{ status: string; database: string; mode: string } | null>(null); const ui = useUiStore(); const runtime = useRuntimeStore(); const workflows = ref<Workflow[]>([]); let refreshTimer: number | undefined
const defaultWorkflow = computed(() => workflows.value.find(item => item.is_default) || workflows.value[0])
async function refreshDashboard(showError = false) { try { [summary.value, health.value, workflows.value] = await Promise.all([getSummary(), getHealth(), getWorkflows()]); await runtime.load() } catch { if (showError) ElMessage.error('暂时无法连接服务，请确认后端已启动') } finally { loading.value = false } }
onMounted(() => { refreshDashboard(true); refreshTimer = window.setInterval(() => refreshDashboard(), 5000) })
onBeforeUnmount(() => { if (refreshTimer) window.clearInterval(refreshTimer) })
const tasks = computed(() => summary.value?.recent_tasks || [])
const weekLabels = computed(() => Array.from({ length: 7 }, (_, index) => { const day = new Date(); day.setDate(day.getDate() - 6 + index); return day.toLocaleDateString('zh-CN', { weekday: 'short' }) }))
const chartOption = computed(() => ({ tooltip: { trigger: 'axis', borderWidth: 0, backgroundColor: ui.theme === 'dark' ? '#171c2a' : '#fff', textStyle: { color: ui.theme === 'dark' ? '#e7ebf5' : '#172033' } }, grid: { left: 2, right: 12, top: 15, bottom: 4, containLabel: true }, xAxis: { type: 'category', boundaryGap: false, data: weekLabels.value, axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#8993a7' } }, yAxis: { type: 'value', show: false, minInterval: 1, splitLine: { lineStyle: { color: ui.theme === 'dark' ? '#2a3142' : '#e6eaf2' } } }, series: [{ data: summary.value?.weekly_task_counts || [], type: 'line', smooth: true, symbol: 'circle', symbolSize: 5, lineStyle: { width: 2.5, color: '#5267F5' }, itemStyle: { color: '#5267F5' }, areaStyle: { color: 'rgba(82,103,245,.08)' } }] }))
async function submitTask() { if (!prompt.value.trim()) return; if (!defaultWorkflow.value) { ElMessage.warning('请先创建并设置默认流程。'); return }; submitting.value = true; try { const input = prompt.value.trim(); const run = await runWorkflow(defaultWorkflow.value.id, { title: input.slice(0, 80), description: input, mode: runtime.mode }); ElMessage.success(`任务已提交：${run.id}`); prompt.value = ''; await refreshDashboard() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message || '任务创建失败，请检查服务状态') } finally { submitting.value = false } }
const currentDate = computed(() => new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }).toUpperCase())
const statusMap: Record<string,{label:string;class:string}> = {succeeded:{label:'已完成',class:'success'},running:{label:'执行中',class:'running'},queued:{label:'排队中',class:'queued'},failed:{label:'失败',class:'failed'},cancelled:{label:'已取消',class:'queued'}}
</script>
<template>
  <div class="dashboard-page">
    <AmbientMotionBackground v-if="ui.ambientMotion" />
    <section class="welcome-row"><div><div class="eyebrow"><span class="eyebrow-line"></span>{{ currentDate }}</div><h1>早上好，欢迎回来 <span class="wave">✦</span></h1><p>把复杂任务交给 AgentFlow，专注于更重要的事。</p></div><el-button text class="range-button">最近 7 天 <el-icon><ArrowRight /></el-icon></el-button></section>
    <section class="task-composer panel"><div class="composer-heading"><div class="composer-icon"><el-icon><Lightning /></el-icon></div><div><h2>今天想完成什么？</h2><p>描述你的目标，AgentFlow 将由默认流程处理</p></div></div><el-input v-model="prompt" type="textarea" :rows="2" resize="none" placeholder="例如：整理本周的用户反馈，归纳主要问题并生成一份简明报告..." @keydown.ctrl.enter="submitTask"/><div class="composer-footer"><div class="composer-meta"><FloatingContent :enabled="ui.ambientMotion" :duration="8.4"><el-tag effect="plain" round>{{ defaultWorkflow?.name || '尚未设置默认流程' }}</el-tag></FloatingContent><span class="meta-separator">·</span><span>{{ runtime.modeLabel }}</span><span class="meta-separator">·</span><span>Ctrl + Enter 快速提交</span></div><el-button type="primary" :loading="submitting" :disabled="!defaultWorkflow" @click="submitTask"><el-icon><Plus /></el-icon>创建任务</el-button></div></section>
    <section class="metrics-grid"><article class="metric-card panel"><div class="metric-top"><span>今日任务 · {{ runtime.modeLabel }}</span><div class="metric-icon blue"><el-icon><Lightning /></el-icon></div></div><div class="metric-value">{{ summary?.today_tasks ?? '—' }}<small> 个</small></div><div class="metric-foot"><span class="foot-muted">按本地日期统计当前环境记录</span></div></article><article class="metric-card panel"><div class="metric-top"><span>任务成功率</span><div class="metric-icon green"><el-icon><CircleCheck /></el-icon></div></div><div class="metric-value">{{ summary?.success_rate == null ? '—' : `${summary.success_rate}%` }}</div><div class="metric-foot"><span class="foot-muted">今日已完成任务</span></div></article><article class="metric-card panel"><div class="metric-top"><span>平均耗时</span><div class="metric-icon amber"><el-icon><Clock /></el-icon></div></div><div class="metric-value">{{ summary?.average_duration_ms == null ? '—' : `${(summary.average_duration_ms / 1000).toFixed(1)}s` }}</div><div class="metric-foot"><span class="foot-muted">今日已完成任务</span></div></article><article class="metric-card panel"><div class="metric-top"><span>Token 消耗</span><div class="metric-icon violet"><el-icon><Coin /></el-icon></div></div><div class="metric-value">{{ summary?.tokens_today == null ? '—' : summary.tokens_today.toLocaleString() }}<small v-if="summary?.tokens_today != null"> tokens</small></div><div class="metric-foot"><span class="foot-muted">{{ runtime.mode === 'demo' ? '安全沙盒不调用模型' : '仅统计模型服务报告的 Token 用量' }}</span></div></article></section>
    <section class="dashboard-columns"><div class="panel activity-panel"><div class="panel-heading"><div><h2>任务活动</h2><p>最近 7 天 · {{ runtime.modeLabel }}</p></div><el-button text class="more-button"><el-icon><MoreFilled /></el-icon></el-button></div><div class="chart-wrap"><v-chart class="activity-chart" :option="chartOption" autoresize /></div><div class="chart-legend"><span class="legend-dot"></span>任务运行数 <span class="legend-note">{{ summary ? (summary.mode === 'live' ? '真实执行记录' : '安全沙盒记录') : '加载中' }}</span></div></div><div class="panel health-panel"><div class="panel-heading"><div><h2>系统状态</h2><p>运行环境概览</p></div><span class="healthy-badge" v-if="health?.status === 'ok'"><i></i>运行正常</span><span class="failed-badge" v-else><i></i>状态未知</span></div><div class="health-list"><div><span class="health-symbol backend">API</span><div class="health-copy"><strong>后端服务</strong><small>FastAPI · 本地运行</small></div><span class="health-state" :class="{ 'health-down': health?.status !== 'ok' }">{{ health?.status === 'ok' ? '正常' : '不可用' }}</span></div><div><span class="health-symbol store">DB</span><div class="health-copy"><strong>数据存储</strong><small>SQLite · 本地数据库</small></div><span class="health-state" :class="{ 'health-down': health?.database !== 'ok' }">{{ health?.database === 'ok' ? '正常' : '不可用' }}</span></div><div><span class="health-symbol mode">{{ runtime.mode === 'live' ? 'AI' : 'SB' }}</span><div class="health-copy"><strong>执行环境</strong><small>{{ runtime.modeCaption }}</small></div><span class="health-state">{{ runtime.modeLabel }}</span></div></div><div class="health-foot"><span class="pulse"></span>后端状态实时查询</div></div></section>
    <section class="panel recent-panel"><div class="panel-heading"><div><h2>最近任务</h2><p>追踪你的智能体执行进度</p></div><el-button text class="view-all" @click="$router.push('/tasks')">查看全部 <el-icon><ArrowRight /></el-icon></el-button></div><div v-if="loading" class="loading-row">正在加载任务…</div><div v-else-if="tasks.length" class="task-table"><div class="task-row task-header"><span>任务</span><span>工作流</span><span>状态</span><span>创建时间</span><span>运行环境</span></div><div v-for="task in tasks.slice(0,4)" :key="task.id" class="task-row"><span class="task-title"><i class="task-mini-icon">✦</i><strong>{{ task.title }}</strong></span><span class="workflow-name">{{ task.workflow }}</span><span><span class="status-pill" :class="statusMap[task.status]?.class"><i></i>{{ statusMap[task.status]?.label }}</span></span><span class="time-cell">{{ new Date(task.created_at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) }}</span><span><el-tag size="small" effect="plain" class="demo-tag">{{ task.mode === 'live' ? 'LIVE' : '沙盒' }}</el-tag></span></div></div><el-empty v-else :image-size="60" description="当前环境还没有任务，试着在上方创建第一个任务吧" /></section>
  </div>
</template>
